def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    last_d = -1

    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
            last_d = i
        if b == 'D':
            opp_d += 1

    opp_c = n - opp_d
    last_me, last_opp = history[-1]

    rec5_d = 0
    start5 = n - 5
    if start5 < 0:
        start5 = 0
    for i in range(start5, n):
        if history[i][1] == 'D':
            rec5_d += 1

    rec10_d = 0
    start10 = n - 10
    if start10 < 0:
        start10 = 0
    for i in range(start10, n):
        if history[i][1] == 'D':
            rec10_d += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == last_opp:
            opp_streak += 1
        else:
            break

    if opp_d == 0:
        if my_d == 0:
            if n >= 80:
                return 'D'
            if n >= 65 and rng.random() < 0.05:
                return 'D'
            if n >= 50 and rng.random() < 0.015:
                return 'D'
            return 'C'
        if my_d == 1 and last_me == 'D':
            return 'C'
        return 'D'

    tolerated = False
    if last_d >= 0 and n - last_d >= 2:
        ok = True
        for j in range(last_d + 1, n):
            if history[j][1] == 'D':
                ok = False
                break
        tolerated = ok

    if last_opp == 'C' and my_d > 0 and tolerated and opp_d <= max(3, n // 12) and rec10_d == 0:
        if n >= 80:
            return 'D'
        if n >= 65 and rng.random() < 0.15:
            return 'D'

    if last_opp == 'C' and opp_d <= max(2, n // 20) and rec10_d == 0:
        if n >= 90 and rng.random() < 0.25:
            return 'D'

    if last_opp == 'D':
        if opp_d >= opp_c or rec10_d >= 5 or opp_streak >= 3:
            return 'D'
        if opp_d > my_d + 1:
            return 'D'

        if last_me == 'D':
            if opp_d <= max(4, n // 8) and rec5_d <= 3:
                return 'C'
            return 'D'

        if my_d >= opp_d:
            return 'C'
        return 'D'

    if opp_d <= n // 2 and my_d > opp_d + 2:
        return 'C'

    if rec10_d >= 4 and opp_d > my_d + 2:
        return 'D'

    return 'C'
